export function getCategoryColor(category: string): string {
  const colors: Record<string, string> = {
    "injury": "orange",
    "fracture": "red",
    "soft_tissue": "blue",
    "condition": "green",
    "neurology": "purple",
    "dental": "cyan",
    "other": "gray",
  };
  return colors[category] ?? "gray";
}
